def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count the number of "descents" where arr[i] > arr[i+1]
    # For a rotated sorted array, there should be at most one descent
    # Also, if there is one descent, the last element must be <= the first element
    descents = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            descents += 1
            if descents > 1:
                return False
    # If there's one descent, check that the last element <= first element
    if descents == 1:
        return arr[-1] <= arr[0]
    return True
```

