def double_the_difference(lst):
    if not lst:
        return 0
    total = 0
    for num in lst:
        if isinstance(num, bool):
            continue
        if not isinstance(num, int):
            continue
        if num < 0:
            continue
        if num % 2 != 0:
            total += num * num
    return total
